import React from 'react';
import { LoadingDots } from '../../../spinner';
import Styled from './TableLoading.styles';

const TableLoading = ({
  span,
  message,
}: {
  span: number | undefined;
  message: string;
}): JSX.Element => (
  <tr>
    <td colSpan={span}>
      <Styled.LoadingContainer>
        <LoadingDots />
        <span>{message}</span>
      </Styled.LoadingContainer>
    </td>
  </tr>
);

export default TableLoading;
